  return { call: vi.fn().mockResolvedValue(returnValue) };
}

function mockSigner(address = '0x' + '1'.repeat(40)) {
  return {
    getAddress: vi.fn().mockResolvedValue(address),
    sendTransaction: vi.fn().mockResolvedValue({
